package com.jagan.healthcare.service;
import com.jagan.healthcare.dto.ChatResponse; import com.jagan.healthcare.model.*; import com.jagan.healthcare.repository.*; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.Collectors;
@Service public class ChatbotService { private final FaqRepository faqRepository; private final SymptomRepository symptomRepository; private final ChatInteractionRepository chatRepository;
 public ChatbotService(FaqRepository f,SymptomRepository s,ChatInteractionRepository c){faqRepository=f;symptomRepository=s;chatRepository=c;}
 public ChatResponse processMessage(String raw){String m=normalize(raw); if(containsAny(m,"hello","hi","hey","good morning","good evening"))return save(raw,"Hello! I can help with general health FAQs, common symptoms, hospitals, doctors and appointments. What would you like to know?","GREETING"); if(containsAny(m,"emergency","unconscious","not breathing","severe chest pain","stroke","heavy bleeding","suicide"))return save(raw,"This may require urgent medical attention. Please contact your local emergency service or go to the nearest emergency department. This chatbot cannot assess emergencies.","EMERGENCY"); if(containsAny(m,"appointment","book doctor","book a doctor","schedule doctor","schedule an appointment","see a doctor","doctor appointment"))return save(raw,"Sure. Please complete the appointment form below.","APPOINTMENT"); if(containsAny(m,"hospital","hospitals","nearby hospital","nearest hospital","hospital list","find hospital","find hospitals"))return save(raw,"Use the Hospital List section below to search the demo hospital directory.","HOSPITAL_LIST"); Faq f=findFaq(m); if(f!=null)return save(raw,f.getAnswer(),"FAQ"); Symptom s=findSymptom(m); if(s!=null)return saveSeverity(raw,"You mentioned \""+s.getSymptomName()+"\".\n\nIs your symptom Minor/Mild or Major/Severe?","SEVERITY_REQUIRED",true,s.getSymptomName()); if(containsAny(m,"thank you","thanks"))return save(raw,"You're welcome. This chatbot provides general information and is not a substitute for professional medical advice.","THANKS"); return save(raw,"I couldn't confidently match that question. Try a common symptom, health FAQ, hospital, doctor, or appointment question.","UNKNOWN");}
 public ChatResponse processSeverity(String symptomName,String severity){Symptom s=findSymptom(normalize(symptomName)); if(s==null)return save(symptomName,"I couldn't identify that symptom. Please describe it again.","UNKNOWN"); String l=normalize(severity); if(l.equals("major")||l.equals("severe"))return save(symptomName+" - MAJOR","Because you described your "+s.getSymptomName()+" as major/severe, please seek prompt medical evaluation. If it is sudden, rapidly worsening, or accompanied by emergency warning signs, seek emergency care. This chatbot cannot diagnose or prescribe treatment.","MAJOR_SYMPTOM"); if(l.equals("minor")||l.equals("mild"))return save(symptomName+" - MINOR",minorGuidance(s),"MINOR_SYMPTOM"); return save(symptomName,"Please select either Minor/Mild or Major/Severe.","SEVERITY_REQUIRED");}
 private String minorGuidance(Symptom s){String n=normalize(s.getSymptomName());StringBuilder b=new StringBuilder("Since you described your "+s.getSymptomName()+" as minor/mild:\n\n");b.append(s.getGuidance());b.append("\n\nGeneral medicine information:"); if(n.contains("headache")){b.append("\n• Paracetamol (acetaminophen) is a commonly used over-the-counter medicine for pain.\n• Check the package label and ask a pharmacist or healthcare professional whether it is appropriate for you.");}else if(n.contains("fever")){b.append("\n• Paracetamol (acetaminophen) is commonly used for fever.\n• Check the package label and ask a pharmacist or healthcare professional whether it is appropriate for you.");}else if(n.contains("cough")){b.append("\n• Cough medicines vary by cough type and cause. Ask a pharmacist or healthcare professional to help choose an appropriate product.");}else{b.append("\n• Medicine choice depends on the cause, age, allergies, existing conditions, and other medicines. Ask a pharmacist or healthcare professional before taking an over-the-counter medicine.");}b.append("\n\nIf symptoms worsen, persist, or become concerning, seek medical attention.");return b.toString();}
 private Faq findFaq(String m){Faq best=null;int score=0;for(Faq f:faqRepository.findAll()){int x=score(m,f.getQuestion()+" "+f.getKeywords());if(x>score){score=x;best=f;}}return score>=1?best:null;} private Symptom findSymptom(String m){Symptom best=null;int score=0;for(Symptom s:symptomRepository.findAll()){int x=score(m,s.getSymptomName()+" "+s.getKeywords());if(x>score){score=x;best=s;}}return score>=1?best:null;} private int score(String m,String t){Set<String>a=tokenize(m),b=tokenize(t);int n=0;for(String w:a)if(w.length()>=3&&b.contains(w))n++;return n;} private Set<String>tokenize(String t){return Arrays.stream(normalize(t).split("\\s+")).filter(w->w.length()>=2).collect(Collectors.toSet());} private String normalize(String t){return t==null?"":t.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9\\s]"," ").replaceAll("\\s+"," ").trim();} private boolean containsAny(String t,String...v){for(String x:v)if(t.contains(x))return true;return false;} private ChatResponse save(String u,String r,String i){chatRepository.save(new ChatInteraction(u,r,i));return new ChatResponse(r,i);} private ChatResponse saveSeverity(String u,String r,String i,boolean req,String s){chatRepository.save(new ChatInteraction(u,r,i));return new ChatResponse(r,i,req,s);}
}
